  let adapter={},initialized=false,state,dialogue=null;
  const freshRecord=()=>({status:'offered',acceptedAt:null,choice:null,counts:{},paid:false});
  function context(value){const raw=plain(value)?value:typeof adapter.readState==='function'?adapter.readState():{};return{season:raw?.season==='cold'?'cold':'hot',region:['farm','mountain','desert'].includes(raw?.region)?raw.region:'farm',scene:text(raw?.scene,24)||'main',playerName:text(raw?.playerName||raw?.name,40)||'Alex Vale'};}
  function fresh(value){const s=context(value);return{version:VERSION,sequence:0,episodeIndex:0,episodes:episodes.map(freshRecord),arcs:Object.fromEntries(IDS.map(id=>[id,[freshRecord(),freshRecord()]])),trust:Object.fromEntries(IDS.map(id=>[id,0])),clues:[],journal:[],recentEventIds:[],coinsEarned:0,season:s.season,cycleId:1,recurring:{},lastRegion:s.region};}
  function emit(name,data){if(typeof adapter[name]==='function')try{adapter[name](data);}catch(e){console.warn('[saga] '+name,e);}}
  const changed=()=>emit('onChange',snapshot());
